def order(api, customer_id="c1", *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_summary_on_empty_shop(api):
    assert api.fulfilment.handle_fulfilment_summary().body == {
        "open_orders": 0, "units_to_pick": 0, "low_stock_products": 0}


def test_summary_counts_open_orders_and_units_excluding_cancelled(shop):
    order(shop, "c1", ("BOOK", 2), ("PEN", 3))  # 5 units
    cancelled = order(shop, "c2", ("LAMP", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 4))  # 4 units
    shop.orders.handle_cancel(cancelled)
    body = shop.fulfilment.handle_fulfilment_summary().body
    assert body["open_orders"] == 2
    assert body["units_to_pick"] == 9


def test_low_stock_counts_active_products_under_five(shop):
    # shop: BOOK=50, LAMP=5, PEN=100 -> none under 5 yet
    assert shop.fulfilment.handle_fulfilment_summary().body["low_stock_products"] == 0
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 400, "on_hand": 4})
    shop.catalog.handle_add_product({"sku": "ALE", "name": "Ale", "unit_price_cents": 400, "on_hand": 0})
    assert shop.fulfilment.handle_fulfilment_summary().body["low_stock_products"] == 2


def test_summary_reflects_orders_and_stock_changes(shop):
    order(shop, "c1", ("LAMP", 5))  # LAMP now 0 on hand -> low stock
    body = shop.fulfilment.handle_fulfilment_summary().body
    assert body == {"open_orders": 1, "units_to_pick": 5, "low_stock_products": 1}

